values ('bbbb0005-0000-4000-8000-00000000002a', 'en', null, 'Technical Writing', 'Technical writing is the craft of explaining how things work and how to use them, clearly enough that a specific reader can act with confidence. This course covers accuracy, audience analysis, plain language, document structure, instructions, visuals, style, editing, accessibility, and the tooling behind modern documentation. Structure adapted from the Technical writing article on Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 88, true, 'humanities', '{}')
